% If If_GP = 1, learning the kernel width for P(Y|X). Set it to 0 can speed up the process!!!

if(width==0)
    width = 0.1;
end
Wt = 1;  % the initial kernel width on C (or T). May need tunning for different data sets!!!
[T,d] = size(X);
X = X * diag(1./std(X));
